  $('#continue-agent').onclick=()=>{if(!state.plan || state.plan!==JSON.stringify(spec())){invalidate();tell('Review the current script and settings first.',true);return;}location.href=`/?project=${encodeURIComponent(state.pid)}&voiceover=reviewed#t=${encodeURIComponent(token || '')}`;};
  $('#approve-generate').onchange=()=>$('#generate').disabled=!$('#approve-generate').checked || !state.plan;
