  async function loadFiles() {if(!state.pid)return;const files=await json(`/api/projects/${encodeURIComponent(state.pid)}/files`);const value=$('#script-file').value;$('#script-file').innerHTML='<option value="">Paste a script below</option>'+files.filter(f=>/\.(txt|md|docx)$/i.test(f.name)).map(f=>`<option value="${esc(f.name)}">${esc(f.name)}</option>`).join('');if([...$('#script-file').options].some(o=>o.value===value))$('#script-file').value=value;}
  $('#script-upload').onchange=()=>run(async()=>{root();const file=$('#script-upload').files[0];if(!file)return;const form=new FormData();form.append('files',file);const result=await(await api(`/api/projects/${encodeURIComponent(state.pid)}/files`,{method:'POST',body:form})).json();await loadFiles();$('#script-file').value=result[0].name;$('#script-file').dispatchEvent(new Event('change'));tell('Script added to this project.');});
